begin;

-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'MATH_SUCCESSIVE_PERCENT_CHANGE';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 12, 'A base muda a cada variação percentual', 'Uma variação percentual incide sobre o valor existente naquele momento. Por isso, a base da segunda etapa costuma ser diferente da base inicial.', 'Em cada etapa, transforme a taxa em um fator multiplicativo: um aumento de p% corresponde a 1 + p/100; uma redução de p% corresponde a 1 - p/100. Multiplique o valor atual pelo fator e use o resultado como nova base. Somar as taxas só funciona em situações especiais; não é uma regra geral.',
    'Um valor de R$ 200 aumenta 10% e depois diminui 10%. Primeiro: 200 x 1,10 = 220. Depois, a redução incide sobre 220: 220 x 0,90 = 198. O resultado não volta a R$ 200 porque as duas taxas incidem sobre bases diferentes.', array['Escreva a base antes de cada etapa.', 'Converta cada aumento ou redução em um fator multiplicativo.', 'Confira se a resposta final tem a unidade e a escala esperadas.']::text[], 5, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v12-math-successive-percent-change","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Calcular porcentagens de uma quantidade.","Interpretar aumentos, reduções e valores de referência."],"key_concepts":["Cada taxa usa a base vigente naquela etapa.","A variação total é relativa ao valor inicial.","Pontos percentuais comparam taxas; variação relativa usa uma taxa-base."],"progression":[],"micro_explanations":[{"id":"math-base","title":"Base vigente","content":"Depois de cada etapa, o resultado passa a ser a base da próxima taxa."},{"id":"math-factor","title":"Fator multiplicativo","content":"Aumento de p% usa 1 + p/100; redução de p% usa 1 - p/100."},{"id":"math-points","title":"Pontos percentuais","content":"A diferença entre duas taxas é expressa em pontos percentuais; a variação relativa usa a taxa inicial como base."},{"id":"math-recovery","title":"Recuperação","content":"Para recuperar uma perda, divida o que falta pelo valor atual, que pode ser menor que a base inicial."}],"remediations":[{"id":"UPDATE_PERCENT_BASE","trigger":"A segunda variação usa a base inicial por engano.","explanation":"A base deve ser atualizada depois de cada etapa.","workedExample":"R$ 100 sobe 20% para R$ 120; uma queda de 20% sobre R$ 120 resulta em R$ 96.","selfCheck":"Qual valor serve de base para a taxa desta etapa?"},{"id":"PERCENTAGE_POINTS","trigger":"Diferença entre taxas é confundida com variação relativa.","explanation":"Subtraia as taxas para obter pontos percentuais e divida a diferença pela taxa inicial para obter a variação relativa.","workedExample":"De 8% para 10% são 2 pontos percentuais; relativamente a 8%, o aumento é 25%.","selfCheck":"A pergunta compara duas taxas ou mede mudança relativa a uma taxa inicial?"},{"id":"RECOVERY_BASE","trigger":"A taxa de recuperação reaplica a redução sobre a base original.","explanation":"A recuperação percentual incide sobre o valor reduzido, que é uma base menor.","workedExample":"Depois de cair de 100 para 90, é preciso aumentar 10/90 ≈ 11,1% para voltar a 100.","selfCheck":"Você dividiu o que falta pela quantidade atual?"}],"source_dossier":[{"title":"Base Nacional Comum Curricular","publisher":"Ministério da Educação, Brasil","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","use":"Referência curricular geral; exemplos, cálculos e questões deste pacote são autorais."},{"title":"Prealgebra 2e, Percent Applications","publisher":"OpenStax","url":"https://openstax.org/details/books/prealgebra-2e","use":"Conferência conceitual sobre porcentagens e fatores; o pacote não reproduz exercícios ou texto da fonte."}],"copyright_note":"Lote V12 autoral com 100 questões e revisão pedagógica pendente; publicação mantida em STAGING.","source_question_feedback":[{"questionId":"v3-mathematics-percentage-6","hint":"Calcule o valor após a alta e use esse novo valor como base do desconto.","errorFocus":"Supor que taxas iguais em sentidos opostos se anulam embora incidam sobre bases diferentes."},{"questionId":"v4-authored-mathematics-successive-probe-01","hint":"Encontre primeiro 120% de R$ 100; depois calcule 10% de desconto sobre esse resultado.","errorFocus":"Aplicar a redução à base inicial em vez do preço reajustado."},{"questionId":"v4-authored-mathematics-successive-probe-02","hint":"O desconto deixa 80% do orçamento; aplique o aumento de 10% ao saldo, não aos R$ 250.","errorFocus":"Usar a base inicial para a segunda variação."},{"questionId":"v4-authored-mathematics-successive-practice-01","hint":"Atualize o kit após o primeiro aumento e aplique o segundo fator ao preço já reajustado.","errorFocus":"Somar duas taxas como se fossem percentuais da mesma base."},{"questionId":"v4-authored-mathematics-successive-practice-02","hint":"Calcule o preço depois do desconto de 25%; só então aplique o reajuste de 20%.","errorFocus":"Aplicar o segundo percentual ao valor original."},{"questionId":"v4-authored-mathematics-successive-transfer-01","hint":"Aplique 1,15 ao aluguel e 0,90 ao valor que resultar; confira se o total faz sentido.","errorFocus":"Somar +15% e -10% sem compor os fatores."},{"questionId":"v4-authored-mathematics-successive-lock-in-01","hint":"Depois da alta de 50%, calcule qual é a base da queda de 50%.","errorFocus":"Tratar percentuais iguais como quantias iguais quando a base mudou."},{"questionId":"v4-authored-mathematics-successive-review-01","hint":"Calcule o reajuste primeiro; a bolsa é 10% do preço reajustado.","errorFocus":"Subtrair a mesma quantia do aumento mesmo quando a segunda taxa usa outra base."},{"questionId":"v4-authored-mathematics-successive-review-02","hint":"Compare os fatores 1,25 e 0,80 e acompanhe os valores após cada etapa.","errorFocus":"Concluir que as taxas se anulam sem verificar as bases e os valores."},{"questionId":"v93-math-successive-01","hint":"Atualize a base depois do aumento antes de calcular o desconto.","errorFocus":"Supor que percentuais iguais em sentidos opostos se anulam."},{"questionId":"v93-math-successive-02","hint":"Calcule primeiro a subtração entre taxas e depois divida pela taxa inicial.","errorFocus":"Usar a mesma unidade para diferença de taxas e aumento relativo."},{"questionId":"v93-math-successive-03","hint":"Calcule o preço após o primeiro desconto e use esse resultado como nova base.","errorFocus":"Aplicar o segundo desconto sobre o preço original."},{"questionId":"v93-math-successive-04","hint":"Multiplique os fatores de aumento e converta o produto de volta em percentual.","errorFocus":"Somar 5% e 4% sem atualizar a base."},{"questionId":"v93-math-successive-05","hint":"Multiplique 500 por 1,08 ou some o acréscimo de R$ 40 ao valor inicial.","errorFocus":"Calcular o acréscimo sem somá-lo à base."},{"questionId":"v93-math-successive-06","hint":"A expressão “sobre o preço com desconto” define a segunda base como R$ 800.","errorFocus":"Calcular os dois descontos sobre R$ 1.000."},{"questionId":"v93-math-successive-07","hint":"Represente o preço final como 0,75 vezes o inicial e resolva a equação.","errorFocus":"Somar 25% de R$ 360 em vez de inverter o fator aplicado."},{"questionId":"v93-math-successive-08","hint":"Use 1,10 em cada etapa; o segundo fator incide sobre 440.","errorFocus":"Somar duas altas de 10% como 20% da base inicial."},{"questionId":"v93-math-successive-09","hint":"Calcule o salário final e subtraia o salário inicial.","errorFocus":"Informar o valor final como se fosse o aumento."},{"questionId":"v93-math-successive-10","hint":"Aplique os fatores de cada oferta ao mesmo preço inicial e compare os resultados.","errorFocus":"Somar descontos sucessivos e comparar taxas sem calcular os preços finais."},{"questionId":"v93-math-successive-11","hint":"Calcule as duas taxas sobre a mesma base de R$ 4.000 e subtraia os valores.","errorFocus":"Aplicar 1% ao valor da comissão em vez da base de vendas."},{"questionId":"v93-math-successive-12","hint":"Multiplique os fatores 1,10 e 0,90 antes de aplicá-los ao preço.","errorFocus":"Presumir cancelamento entre percentuais iguais."},{"questionId":"v93-math-successive-13","hint":"Divida a diferença entre taxas pela taxa inicial.","errorFocus":"Responder com pontos percentuais quando a pergunta pede variação relativa."},{"questionId":"v93-math-successive-14","hint":"Aplique o fator 0,88 duas vezes, preservando o valor atualizado entre anos.","errorFocus":"Aplicar a depreciação anual somente uma vez ou sempre sobre o valor inicial."},{"questionId":"v93-math-successive-15","hint":"Calcule separadamente o valor da alta e o valor do desconto.","errorFocus":"Ignorar que a base mudou entre as etapas."},{"questionId":"v93-math-successive-16","hint":"Use o total da primeira cobrança como base da segunda.","errorFocus":"Somar 8% + 8% sobre a base inicial."},{"questionId":"v93-math-successive-17","hint":"Siga a ordem descrita: desconto no produto, depois adição do frete.","errorFocus":"Aplicar o desconto ao frete mesmo quando ele é fixo e cobrado depois."},{"questionId":"v93-math-successive-18","hint":"Subtraia o desconto de R$ 10 do preço inicial.","errorFocus":"Responder com o valor do desconto em vez do preço após desconto."},{"questionId":"v93-math-successive-19","hint":"Multiplique duas vezes por 1,02 e confira o acréscimo em relação a 500.","errorFocus":"Somar taxas sucessivas como variação linear."},{"questionId":"v93-math-successive-20","hint":"A recuperação parte de 150; divida a diferença de 50 pelo valor atual.","errorFocus":"Usar o valor inicial 200 como base da recuperação."}],"objective":"Calcular variações percentuais sucessivas, atualizando a base em cada etapa.","common_mistake":"Somar as taxas sucessivas ou supor que percentuais iguais em sentidos opostos sempre se anulam.","estimated_minutes":5}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 12
     and metadata->>'content_id' = 'v12-math-successive-percent-change' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-math-successive-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"APPLY","contextFamily":"MENSALIDADE","statement":"Uma mensalidade de R$ 80 recebe reajuste de 15%. No mês seguinte, o novo valor recebe desconto de 10%. Qual é o valor final?","options":["R$ 80,00","R$ 84,00","R$ 92,00","R$ 82,80"],"correctAnswer":"R$ 82,80","explanation":"O reajuste leva a mensalidade a R$ 92,00. O desconto seguinte usa R$ 92,00 como base: 92 x 0,90 = R$ 82,80.","hint":"Calcule primeiro o valor depois do reajuste; use esse resultado como base do desconto.","errorFocus":"BASE_DA_SEGUNDA_ETAPA","misconceptions":{"R$ 84,00":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":1},{"id":"v5-math-successive-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"APPLY","contextFamily":"RESERVA_FINANCEIRA","statement":"Uma reserva de R$ 200 cresce 10% em um mês e mais 5% no mês seguinte. Qual é o saldo ao final das duas etapas?","options":["R$ 210,00","R$ 231,00","R$ 220,00","R$ 230,00"],"correctAnswer":"R$ 231,00","explanation":"A primeira etapa resulta em R$ 220,00. Cinco por cento de R$ 220,00 são R$ 11,00, totalizando R$ 231,00.","hint":"O segundo aumento incide sobre o saldo depois do primeiro aumento, não sobre R$ 200,00.","errorFocus":"TAXAS_SOMADAS","misconceptions":{"R$ 230,00":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":2},{"id":"v5-math-successive-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"COMPRA_DE_MATERIAL","statement":"Uma compra de R$ 250 recebe desconto de 12%. Depois, o valor com desconto sofre aumento de 8%. Quanto passa a custar?","options":["R$ 237,60","R$ 220,00","R$ 240,00","R$ 270,00"],"correctAnswer":"R$ 237,60","explanation":"Depois do desconto: 250 x 0,88 = R$ 220,00. O aumento incide sobre R$ 220,00: 220 x 1,08 = R$ 237,60.","hint":"Represente o desconto por 0,88 e o aumento seguinte por 1,08.","errorFocus":"ORDEM_E_BASE","misconceptions":{"R$ 240,00":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":1},{"id":"v5-math-successive-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"PLANO_DE_ASSINATURA","statement":"Um plano custa R$ 120,00. O preço aumenta 5% em cada um de dois meses consecutivos. Qual é o preço depois do segundo aumento?","options":["R$ 126,00","R$ 132,00","R$ 132,30","R$ 133,20"],"correctAnswer":"R$ 132,30","explanation":"Após o primeiro aumento, 120 x 1,05 = R$ 126,00. No segundo mês, 126 x 1,05 = R$ 132,30.","hint":"Aplique o fator 1,05 duas vezes, atualizando o valor entre as multiplicações.","errorFocus":"REUTILIZACAO_DA_BASE_INICIAL","misconceptions":{"R$ 132,00":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":2},{"id":"v5-math-successive-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"POPULACAO_DE_PEIXES","statement":"Um viveiro tinha 1.200 peixes. A população diminuiu 15% e, depois, aumentou 15% em relação ao total restante. Quantos peixes havia ao final, considerando o modelo percentual?","options":["1.020","1.173","1.200","1.380"],"correctAnswer":"1.173","explanation":"A diminuição deixa 1.200 x 0,85 = 1.020. O aumento seguinte é 15% de 1.020, isto é, 153; o total passa a 1.173.","hint":"A expressão ''em relação ao total restante'' define a base do aumento final.","errorFocus":"PERCENTUAL_SOBRE_RESTANTE","misconceptions":{"1.200":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":1},{"id":"v5-math-successive-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"CAPACIDADE_DE_RESERVATORIO","statement":"Um reservatório comporta 800 mil litros. Uma obra reduz temporariamente a capacidade em 12,5%; uma ampliação posterior aumenta em 20% a capacidade já reduzida. Qual fica sendo a capacidade?","options":["700 mil litros","800 mil litros","840 mil litros","860 mil litros"],"correctAnswer":"840 mil litros","explanation":"A redução de 12,5% corresponde a multiplicar por 0,875: 800 x 0,875 = 700. A ampliação de 20% usa 700 como base: 700 x 1,20 = 840 mil litros.","hint":"Escreva cada etapa como um fator e aplique o segundo fator ao resultado da primeira.","errorFocus":"CONVERSAO_PARA_FATOR","misconceptions":{"860 mil litros":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":2},{"id":"v5-math-successive-lock-in-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"AREA_PLANTADA","statement":"Uma área plantada de 100 hectares aumenta 30% em um ano e diminui 20% no seguinte. Qual afirmação descreve corretamente o resultado?","options":["Fica com 104 hectares porque a redução incide sobre 130.","Volta a 100 hectares porque as taxas se anulam.","Fica com 110 hectares porque o saldo das taxas é 10%.","Fica com 130 hectares porque a redução não altera a base."],"correctAnswer":"Fica com 104 hectares porque a redução incide sobre 130.","explanation":"O aumento leva a área a 130 hectares. Vinte por cento de 130 são 26; restam 104 hectares.","hint":"Antes de calcular a redução, determine a área após o aumento de 30%.","errorFocus":"VARIACAO_TOTAL_VS_SALDO_DAS_TAXAS","misconceptions":{"Volta a 100 hectares porque as taxas se anulam.":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":1},{"id":"v5-math-successive-lock-in-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"EVOLUCAO_SALARIAL","statement":"Um salário de R$ 600 recebe aumento de 12% e, no período seguinte, redução de 12% sobre o novo salário. Qual valor resulta?","options":["R$ 591,36","R$ 528,00","R$ 600,00","R$ 672,00"],"correctAnswer":"R$ 591,36","explanation":"O aumento resulta em R$ 672,00. A redução é 12% de R$ 672,00, ou R$ 80,64; restam R$ 591,36.","hint":"Taxas iguais em sentidos opostos não se anulam quando usam bases diferentes.","errorFocus":"CANCELAMENTO_INDEVIDO","misconceptions":{"R$ 600,00":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":2},{"id":"v5-math-successive-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"COMPARACAO_DE_INVESTIMENTOS","statement":"Um aporte de R$ 1.000 rende 5% em cada um de dois períodos. Outro aporte igual rende 10% uma única vez. Qual comparação dos valores finais é correta?","options":["Os dois terminam em R$ 1.100,00.","Dois períodos de 5% terminam em R$ 1.102,50, R$ 2,50 acima do rendimento único de 10%.","Dois períodos de 5% terminam em R$ 1.105,00, R$ 5,00 acima.","O rendimento único termina acima, em R$ 1.150,00."],"correctAnswer":"Dois períodos de 5% terminam em R$ 1.102,50, R$ 2,50 acima do rendimento único de 10%.","explanation":"O fator dos dois períodos é 1,05 x 1,05 = 1,1025. Em R$ 1.000, isso resulta em R$ 1.102,50; um aumento único de 10% resulta em R$ 1.100,00.","hint":"Compare os fatores finais: 1,05 x 1,05 e 1,10.","errorFocus":"COMPOSICAO_DE_FATORES","misconceptions":{"Os dois terminam em R$ 1.100,00.":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":1},{"id":"v5-math-successive-review-02","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"RECONSTRUCAO_DE_VALOR","statement":"Depois de uma redução de 10% e de um aumento de 20% sobre o valor reduzido, um equipamento custa R$ 108,00. Qual era o valor inicial?","options":["R$ 90,00","R$ 108,00","R$ 120,00","R$ 100,00"],"correctAnswer":"R$ 100,00","explanation":"O fator combinado é 0,90 x 1,20 = 1,08. Portanto, valor inicial x 1,08 = R$ 108,00, e o valor inicial era R$ 100,00.","hint":"Encontre primeiro o fator combinado e divida o valor final por ele.","errorFocus":"RACIOCINIO_INVERSO_COM_FATORES","misconceptions":{"R$ 108,00":["SUCCESSIVE_PERCENTAGES_CANCELLED"]},"position":2},{"id":"v6-math-successive-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"COLETA_SELETIVA","statement":"Um ponto de coleta recebeu 2.500 kg de recicláveis em um mês. No mês seguinte, o total cresceu 12%; depois, caiu 5% em relação ao novo total. Qual foi o resultado final e a variação em relação ao primeiro mês?","options":["2.660 kg; aumento de 6,4%.","2.650 kg; aumento de 6%.","2.800 kg; aumento de 12%.","2.660 kg; aumento de 12%."],"correctAnswer":"2.660 kg; aumento de 6,4%.","explanation":"A primeira etapa dá 2.500 × 1,12 = 2.800 kg. A redução usa 2.800 como base: 2.800 × 0,95 = 2.660 kg. O acréscimo de 160 kg corresponde a 160 ÷ 2.500 = 6,4%.","hint":"Registre o total depois do crescimento; aplique a queda sobre esse total e compare o resultado com 2.500 kg.","errorFocus":"BASE_ATUALIZADA_E_VARIACAO_TOTAL","misconceptions":{"2.650 kg; aumento de 6%.":["SOMAR_TAXAS_SEM_ATUALIZAR_BASE"],"2.800 kg; aumento de 12%.":["IGNORAR_SEGUNDA_ETAPA"],"2.660 kg; aumento de 12%.":["CONFUNDIR_VARIACAO_DA_ETAPA_COM_VARIACAO_TOTAL"]},"position":3},{"id":"v6-math-successive-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REVISAO_DE_CONTA","statement":"Uma tarifa de R$ 250 aumenta 20% e, no período seguinte, recebe desconto de 20%. Caio afirma que o valor volta a R$ 250 porque “mais 20 e menos 20 se anulam”. Qual análise corrige o raciocínio?","options":["Volta a R$ 250, pois taxas com o mesmo número sempre se anulam.","Termina em R$ 240: a queda é 20% de R$ 300, então fica R$ 10 abaixo do início.","Termina em R$ 250, pois o desconto de R$ 60 é calculado sobre a base inicial.","Termina em R$ 300, pois só o aumento altera o valor."],"correctAnswer":"Termina em R$ 240: a queda é 20% de R$ 300, então fica R$ 10 abaixo do início.","explanation":"A tarifa sobe de R$ 250 para R$ 300. O desconto é 20% de R$ 300, isto é, R$ 60; o valor final é R$ 240. A redução de R$ 60 não é igual ao aumento inicial de R$ 50.","hint":"Calcule primeiro o aumento em reais; em seguida, encontre 20% do valor já aumentado.","errorFocus":"PERCENTUAIS_IGUAIS_NAO_SAO_QUANTIAS_IGUAIS","misconceptions":{"Volta a R$ 250, pois taxas com o mesmo número sempre se anulam.":["CANCELAMENTO_INDEVIDO"],"Termina em R$ 250, pois o desconto de R$ 60 é calculado sobre a base inicial.":["BASE_INICIAL_REUTILIZADA"],"Termina em R$ 300, pois só o aumento altera o valor.":["ETAPA_IGNORADA"]},"position":3},{"id":"v6-math-successive-review-02","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"ESTOQUE_DE_REAGENTES","statement":"Um laboratório tinha 40 kg de um reagente. O estoque caiu 30% e, no mês seguinte, cresceu 30% sobre o estoque restante. Qual alternativa informa corretamente a quantidade final e sua relação com a inicial?","options":["40 kg; voltou ao valor inicial porque as taxas se anulam.","36,4 kg; ficou 3,6% abaixo do valor inicial.","36,4 kg; ficou 9% abaixo do valor inicial.","28 kg; a segunda variação não altera a quantidade."],"correctAnswer":"36,4 kg; ficou 9% abaixo do valor inicial.","explanation":"Após a queda, restam 40 × 0,70 = 28 kg. O aumento é 30% de 28, ou 8,4 kg, levando o estoque a 36,4 kg. A perda de 3,6 kg equivale a 9% dos 40 kg iniciais.","hint":"Atualize o estoque após a queda. Depois compare o total final com 40 kg, que é a base da variação total.","errorFocus":"COMPOSICAO_E_BASE_DA_VARIACAO_TOTAL","misconceptions":{"40 kg; voltou ao valor inicial porque as taxas se anulam.":["CANCELAMENTO_INDEVIDO"],"36,4 kg; ficou 3,6% abaixo do valor inicial.":["DIFERENCA_ABSOLUTA_LIDA_COMO_PERCENTUAL"],"28 kg; a segunda variação não altera a quantidade.":["ETAPA_IGNORADA"]},"position":4},{"id":"v6-math-successive-review-03","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"CONSUMO_DE_ENERGIA","statement":"Uma instalação reduziu o consumo mensal de 2.500 kWh em 10%. Para voltar exatamente a 2.500 kWh, qual aumento percentual deve incidir sobre o consumo já reduzido?","options":["10%, pois a redução e a recuperação usam a mesma taxa.","12,5%, pois basta acrescentar metade da redução percentual.","25%, pois 250 kWh correspondem a um quarto do consumo atual.","11,1% aproximadamente, pois o aumento incide sobre 2.250 kWh."],"correctAnswer":"11,1% aproximadamente, pois o aumento incide sobre 2.250 kWh.","explanation":"Após reduzir 10%, o consumo é 2.250 kWh. Para recuperar 250 kWh, a taxa é 250 ÷ 2.250 ≈ 0,1111, ou 11,1%. A base menor exige uma taxa percentual maior para recuperar a mesma quantidade.","hint":"Calcule o consumo reduzido e divida os 250 kWh que faltam por essa nova base.","errorFocus":"PERCENTUAL_DE_RECUPERACAO_USA_BASE_MENOR","misconceptions":{"10%, pois a redução e a recuperação usam a mesma taxa.":["REAPLICAR_TAXA_SOBRE_BASE_DIFERENTE"],"12,5%, pois basta acrescentar metade da redução percentual.":["AJUSTE_PROPORCIONAL_SEM_BASE"],"25%, pois 250 kWh correspondem a um quarto do consumo atual.":["DENOMINADOR_INCORRETO"]},"position":5},{"id":"v12-math-successive-percent-change-001","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V12_MATH_SUCCESSIVE_FACTOR_01","statement":"Um caderno custa R$ 100 e recebe aumento de 20%. Qual fator representa o novo preço?","options":["1,20, pois o preço conserva 100% e recebe mais 20%.","0,20, porque só a taxa deve ser usada.","1,02, porque 20% equivale a 2%.","20,00, porque fator não pode ser decimal."],"correctAnswer":"1,20, pois o preço conserva 100% e recebe mais 20%.","explanation":"A resposta atualiza a base e respeita o tipo de comparação pedido. Converta aumento percentual em fator multiplicativo antes de calcular.","hint":"Escreva a base, transforme a taxa em fator e acompanhe cada etapa antes de comparar.","errorFocus":"MATH_SUCCESSIVE_PERCENT_BASE_CONFUSION","misconceptions":{"0,20, porque só a taxa deve ser usada.":["MATH_SUCCESSIVE_PERCENT_BASE_CONFUSION"]},"position":3},{"id":"v12-math-successive-percent-change-002","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"V12_MATH_SUCCESSIVE_FACTOR_02","statement":"Um caderno custa R$ 100 e recebe aumento de 20%. Qual critério deve orientar o cálculo?","option